          probabilities:threeWay(difference+params.goalWeight*(mean(h)-mean(a)),params.drawBase),
          rating:threeWay(difference,.26),frequency:state.counts.map(v=>v/state.counts.reduce((x,y)=>x+y,0)),uniform:[1/3,1/3,1/3]});
